using TMPro;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;

public static class CreateRoomClayRestyle
{
    private static readonly Color Canvas = Hex("#fffaf0");
    private static readonly Color SurfaceCard = Hex("#f5f0e0");
    private static readonly Color SurfaceSoft = Hex("#faf5e8");
    private static readonly Color Ink = Hex("#0a0a0a");
    private static readonly Color Body = Hex("#3a3a3a");
    private static readonly Color Muted = Hex("#6a6a6a");
    private static readonly Color BrandPink = Hex("#ff4d8b");
    private static readonly Color BrandTeal = Hex("#1a3a3a");
    private static readonly Color OnPrimary = Color.white;

    public static string Run()
    {
        var canvasGo = GameObject.Find("RoomCanvas");
        if (canvasGo == null) return "RoomCanvas not found";

        var roomUi = Object.FindFirstObjectByType<MultiplayerRoomUI>();
        if (roomUi == null) return "MultiplayerRoomUI not found";

        StyleBackground(FindChild(canvasGo.transform, "RoomUI/Background"), Canvas);
        StylePanel(FindChild(canvasGo.transform, "RoomUI/MainPanel"), SurfaceCard);
        StylePanel(FindChild(canvasGo.transform, "RoomUI/HostPanel"), SurfaceCard);
        StylePanel(FindChild(canvasGo.transform, "RoomUI/JoinPanel"), SurfaceCard);

        StyleTitle(FindChild(canvasGo.transform, "RoomUI/MainPanel/TitleText"), "Create Room", 48);
        StyleBody(FindChild(canvasGo.transform, "RoomUI/MainPanel/StatusText"), Muted, 18);

        StyleTitle(FindChild(canvasGo.transform, "RoomUI/HostPanel/HostTitle"), "Your Room Code", 36);
        var hostCodeGo = FindChild(canvasGo.transform, "RoomUI/HostPanel/HostRoomCodeText");
        var hostStatusGo = FindChild(canvasGo.transform, "RoomUI/HostPanel/HostStatusText");
        StyleCode(hostCodeGo);
        StyleBody(hostStatusGo, Body, 20);
        LayoutRect(hostCodeGo, 0.55f, new Vector2(560, 110));
        LayoutRect(hostStatusGo, 0.35f, new Vector2(520, 50));
        LayoutRect(FindChild(canvasGo.transform, "RoomUI/HostPanel/HostTitle"), 0.82f, new Vector2(520, 60));

        StyleTitle(FindChild(canvasGo.transform, "RoomUI/JoinPanel/JoinTitle"), "Enter Room Code", 36);
        LayoutRect(FindChild(canvasGo.transform, "RoomUI/JoinPanel/JoinTitle"), 0.78f, new Vector2(520, 60));
        StyleInput(FindChild(canvasGo.transform, "RoomUI/JoinPanel/JoinCodeInput"));
        LayoutRect(FindChild(canvasGo.transform, "RoomUI/JoinPanel/JoinCodeInput"), 0.52f, new Vector2(420, 64));

        StylePrimaryButton(FindChild(canvasGo.transform, "RoomUI/MainPanel/HostButton"), BrandTeal);
        StylePrimaryButton(FindChild(canvasGo.transform, "RoomUI/MainPanel/JoinButton"), BrandPink);
        StylePrimaryButton(FindChild(canvasGo.transform, "RoomUI/JoinPanel/ConfirmJoinButton"), BrandTeal);
        StyleSecondaryButton(FindChild(canvasGo.transform, "RoomUI/HostPanel/HostBackButton"));
        StyleSecondaryButton(FindChild(canvasGo.transform, "RoomUI/JoinPanel/JoinBackButton"));
        StyleSecondaryButton(FindChild(canvasGo.transform, "RoomUI/HostPanel/LeaveButton"));

        LayoutRect(FindChild(canvasGo.transform, "RoomUI/MainPanel/HostButton"), 0.58f, new Vector2(300, 56));
        LayoutRect(FindChild(canvasGo.transform, "RoomUI/MainPanel/JoinButton"), 0.42f, new Vector2(300, 56));
        LayoutRect(FindChild(canvasGo.transform, "RoomUI/MainPanel/TitleText"), 0.78f, new Vector2(560, 70));
        LayoutRect(FindChild(canvasGo.transform, "RoomUI/MainPanel/StatusText"), 0.18f, new Vector2(560, 40));
        LayoutRect(FindChild(canvasGo.transform, "RoomUI/HostPanel/HostBackButton"), 0.12f, new Vector2(260, 52));
        LayoutRect(FindChild(canvasGo.transform, "RoomUI/HostPanel/LeaveButton"), 0.12f, new Vector2(260, 52));
        LayoutRect(FindChild(canvasGo.transform, "RoomUI/JoinPanel/ConfirmJoinButton"), 0.34f, new Vector2(300, 56));
        LayoutRect(FindChild(canvasGo.transform, "RoomUI/JoinPanel/JoinBackButton"), 0.18f, new Vector2(260, 52));

        var uiSo = new SerializedObject(roomUi);
        uiSo.FindProperty("hostRoomCodeText").objectReferenceValue = hostCodeGo != null ? hostCodeGo.GetComponent<TMP_Text>() : null;
        uiSo.FindProperty("hostStatusText").objectReferenceValue = hostStatusGo != null ? hostStatusGo.GetComponent<TMP_Text>() : null;
        uiSo.FindProperty("statusText").objectReferenceValue = FindChild(canvasGo.transform, "RoomUI/MainPanel/StatusText")?.GetComponent<TMP_Text>();
        uiSo.FindProperty("joinCodeInput").objectReferenceValue = FindChild(canvasGo.transform, "RoomUI/JoinPanel/JoinCodeInput")?.GetComponent<TMP_InputField>();
        uiSo.FindProperty("hostButton").objectReferenceValue = FindChild(canvasGo.transform, "RoomUI/MainPanel/HostButton")?.GetComponent<Button>();
        uiSo.FindProperty("joinButton").objectReferenceValue = FindChild(canvasGo.transform, "RoomUI/MainPanel/JoinButton")?.GetComponent<Button>();
        uiSo.FindProperty("leaveButton").objectReferenceValue = FindChild(canvasGo.transform, "RoomUI/HostPanel/LeaveButton")?.GetComponent<Button>();
        uiSo.FindProperty("mainPanel").objectReferenceValue = FindChild(canvasGo.transform, "RoomUI/MainPanel");
        uiSo.FindProperty("hostPanel").objectReferenceValue = FindChild(canvasGo.transform, "RoomUI/HostPanel");
        uiSo.FindProperty("joinPanel").objectReferenceValue = FindChild(canvasGo.transform, "RoomUI/JoinPanel");
        uiSo.ApplyModifiedPropertiesWithoutUndo();

        var camera = Camera.main;
        if (camera != null)
        {
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = Canvas;
        }

        EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());
        return "Clay restyle applied";
    }

    private static GameObject FindChild(Transform root, string path)
    {
        var current = root;
        foreach (var part in path.Split('/'))
        {
            if (current == null) return null;
            current = current.Find(part);
        }
        return current != null ? current.gameObject : null;
    }

    private static void StyleBackground(GameObject go, Color color)
    {
        if (go == null) return;
        var image = go.GetComponent<Image>();
        if (image != null) image.color = color;
    }

    private static void StylePanel(GameObject go, Color color)
    {
        if (go == null) return;
        var image = go.GetComponent<Image>();
        if (image != null)
        {
            image.color = color;
            ApplyRoundedSprite(image);
        }
        var rect = go.GetComponent<RectTransform>();
        if (rect != null) rect.sizeDelta = new Vector2(760, 560);
    }

    private static void StyleTitle(GameObject go, string text, float size)
    {
        if (go == null) return;
        var tmp = go.GetComponent<TMP_Text>();
        if (tmp == null) return;
        tmp.text = text;
        tmp.fontSize = size;
        tmp.fontStyle = FontStyles.Bold;
        tmp.color = Ink;
        tmp.alignment = TextAlignmentOptions.Center;
    }

    private static void StyleBody(GameObject go, Color color, float size)
    {
        if (go == null) return;
        var tmp = go.GetComponent<TMP_Text>();
        if (tmp == null) return;
        tmp.fontSize = size;
        tmp.color = color;
        tmp.alignment = TextAlignmentOptions.Center;
    }

    private static void StyleCode(GameObject go)
    {
        if (go == null) return;
        var tmp = go.GetComponent<TMP_Text>();
        if (tmp == null) return;
        tmp.fontSize = 84;
        tmp.fontStyle = FontStyles.Bold;
        tmp.color = BrandTeal;
        tmp.alignment = TextAlignmentOptions.Center;
        tmp.characterSpacing = 8f;
    }

    private static void StyleInput(GameObject go)
    {
        if (go == null) return;
        var image = go.GetComponent<Image>();
        if (image != null)
        {
            image.color = Canvas;
            ApplyRoundedSprite(image);
        }
        var text = go.transform.Find("Text")?.GetComponent<TMP_Text>();
        if (text != null)
        {
            text.color = Ink;
            text.fontSize = 40;
            text.alignment = TextAlignmentOptions.Center;
        }
        var placeholder = go.transform.Find("Placeholder")?.GetComponent<TMP_Text>();
        if (placeholder != null)
        {
            placeholder.color = Muted;
            placeholder.text = "ABC123";
        }
    }

    private static void StylePrimaryButton(GameObject go, Color bg)
    {
        if (go == null) return;
        var image = go.GetComponent<Image>();
        if (image != null)
        {
            image.color = bg;
            ApplyRoundedSprite(image);
        }
        var text = go.GetComponentInChildren<TMP_Text>();
        if (text != null)
        {
            text.color = OnPrimary;
            text.fontSize = 20;
            text.fontStyle = FontStyles.Bold;
        }
    }

    private static void StyleSecondaryButton(GameObject go)
    {
        if (go == null) return;
        var image = go.GetComponent<Image>();
        if (image != null)
        {
            image.color = SurfaceSoft;
            ApplyRoundedSprite(image);
        }
        var text = go.GetComponentInChildren<TMP_Text>();
        if (text != null)
        {
            text.color = Ink;
            text.fontSize = 18;
            text.fontStyle = FontStyles.Bold;
        }
    }

    private static void LayoutRect(GameObject go, float anchorY, Vector2 size)
    {
        if (go == null) return;
        var rect = go.GetComponent<RectTransform>();
        rect.anchorMin = new Vector2(0.5f, anchorY);
        rect.anchorMax = new Vector2(0.5f, anchorY);
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.sizeDelta = size;
        rect.anchoredPosition = Vector2.zero;
    }

    private static void ApplyRoundedSprite(Image image)
    {
        var sprite = AssetDatabase.GetBuiltinExtraResource<Sprite>("UI/Skin/UISprite.psd");
        if (sprite != null)
        {
            image.sprite = sprite;
            image.type = Image.Type.Sliced;
        }
    }

    private static Color Hex(string hex)
    {
        return ColorUtility.TryParseHtmlString(hex, out var color) ? color : Color.white;
    }
}
